// A parse context as zod 3 keeps it: the issue list starts as `[]` in a
// nested literal, and the path is the caller's array or `[]`.
export function makeIssue(params) {
  const { path, issueData } = params;
  const fullPath = [...path, ...(issueData.path || [])];
  return { ...issueData, path: fullPath, message: "m" };
}
export function addIssue(ctx, issueData) {
  const issue = makeIssue({ issueData, path: ctx.path });
  ctx.common.issues.push(issue);
}
export class Schema {
  safeParse(data, params) {
    const ctx = {
      common: { issues: [], async: params?.async ?? false },
      path: params?.path || [],
      data,
    };
    if (typeof data !== "string") addIssue(ctx, { code: "invalid_type" });
    return ctx.common.issues.length === 0 ? { success: true, data } : { success: false, issues: ctx.common.issues };
  }
}
// Array properties of records in an array literal and in a deeper literal,
// filled after construction.
export function rows() {
  const table = { rows: [{ cells: [] }, { cells: [] }], meta: { tags: { list: [] } }, size: 2 };
  table.rows[0].cells.push({ v: 1 });
  table.rows[1].cells.push("text", 3);
  table.meta.tags.list.push({ name: "t" }, null);
  return JSON.stringify(table);
}
